package vn.iotstar.service.impl;import com.cloudinary.Cloudinary;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import vn.iotstar.service.*;import java.util.Map;@Service public class CloudinaryServiceImpl implements CloudinaryService{public CloudinaryServiceImpl(Cloudinary cloud){this.cloud=cloud;}final Cloudinary cloud;public CloudinaryUploadResult upload(MultipartFile f){if(f==null||f.isEmpty())throw new IllegalArgumentException("Chưa chọn ảnh");if(f.getContentType()==null||!f.getContentType().startsWith("image/"))throw new IllegalArgumentException("Chỉ cho phép file hình ảnh");try{Map<?,?> r=cloud.uploader().upload(f.getBytes(),Map.of("folder","shop/products"));return new CloudinaryUploadResult(String.valueOf(r.get("secure_url")),String.valueOf(r.get("public_id")));}catch(Exception e){throw new IllegalStateException("Upload Cloudinary thất bại",e);}}public void delete(String id){if(id==null||id.isBlank())return;try{cloud.uploader().destroy(id,Map.of("resource_type","image"));}catch(Exception e){throw new IllegalStateException("Xóa ảnh Cloudinary thất bại",e);}}}
